#include <bits/stdc++.h>
using namespace std;

int main() {
    int n, m;
    cin >> n >> m;
    if (n >= 4 && m >= 4) {
        cout << n * m - (n * m % 2) << "\n";
    } else {
        int min_nm = min(n, m);
        int max_nm = max(n, m);
        if (min_nm == 1) {
            int r = max_nm;
            int mod6 = r % 6;
            if (mod6 == 5) {
                cout << (r / 6) * 6 + 4 << "\n";
            } else if (mod6 == 4) {
                cout << (r / 6) * 6 + 2 << "\n";
            } else {
                cout << (r / 6) * 6 << "\n";
            }
        } else if (min_nm == 2 && max_nm == 7) {
            cout << 12 << "\n";
        } else if ((min_nm == 2 && max_nm >= 4) || (min_nm == 3 && max_nm >= 4)) {
            cout << n * m - (n * m % 2) << "\n";
        } else {
            int lookup[5][5] = {
                {0, 0, 0, 2, 4},
                {0, 0, 4, 8, 10},
                {0, 0, 8, 12, 14},
                {0, 0, 0, 16, 20},
                {0, 0, 0, 0, 24}
            };
            cout << lookup[min_nm - 1][max_nm - 1] << "\n";
        }
    }
    return 0;
}
